package main

import "fmt"

func kind(v any) string {
    switch t := v.(type) {
    case int:
        return fmt.Sprintf("int:%d", t*2)
    case string:
        return "string:" + t
    default:
        return "other"
    }
}

func main() {
    fmt.Println(kind(21))
    fmt.Println(kind("го"))
    fmt.Println(kind(3.14))
}
